#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int n1 = n / 2;
    vector<int> a1, a2;
    a1.reserve(1 << n1);
    a2.reserve(1 << (n - n1));

    function<void(int, int)> generate_sums1 = [&](int i, int total) {
        if (i == n1) {
            a1.push_back(total % m);
        } else {
            generate_sums1(i + 1, total + a[i]);
            generate_sums1(i + 1, total);
        }
    };

    function<void(int, int)> generate_sums2 = [&](int i, int total) {
        if (i == n) {
            a2.push_back(total % m);
        } else {
            generate_sums2(i + 1, total + a[i]);
            generate_sums2(i + 1, total);
        }
    };

    generate_sums1(0, 0);
    generate_sums2(n1, 0);

    int max_sum = 0;
    std::set<int> a1_set(a1.begin(), a1.end());
    std::vector<int> a1_unique(a1_set.begin(), a1_set.end());

    for (int i : a2) {
        int j = (int)(std::lower_bound(a1_unique.begin(), a1_unique.end(), m - i) - a1_unique.begin());
        if (j > 0) {
            int candidate = a1_unique[j - 1] + i;
            if (candidate > max_sum) {
                max_sum = candidate;
            }
        }
    }

    cout << max_sum << "\n";

    return 0;
}
